var a=[{slug:"gastroenterologia",nazwa:"Gastroenterologia",opis:["Zapewniamy kompleksow\u0105 opiek\u0119 gastroenterologiczn\u0105 dla dzieci i doros\u0142ych, obejmuj\u0105c\u0105 konsultacje specjalistyczne, nowoczesn\u0105 diagnostyk\u0119 endoskopow\u0105 oraz leczenie chor\xF3b przewodu pokarmowego. Naszym celem jest szybkie i trafne rozpoznanie dolegliwo\u015Bci oraz wdro\u017Cenie skutecznej, indywidualnie dobranej terapii.","Specjalizujemy si\u0119 w diagnostyce schorze\u0144 prze\u0142yku, \u017Co\u0142\u0105dka, jelita cienkiego i grubego, takich jak m.in. refluks, choroba wrzodowa, zesp\xF3\u0142 jelita dra\u017Cliwego (IBS), nieswoiste choroby zapalne jelit (np. choroba Crohna, wrzodziej\u0105ce zapalenie jelita grubego), a tak\u017Ce w profilaktyce i wczesnym wykrywaniu zmian nowotworowych.","Prowadzimy konsultacje gastroenterologiczne dla doros\u0142ych i dla dzieci. Podczas wizyty lekarz przeprowadza szczeg\xF3\u0142owy wywiad, analizuje wyniki bada\u0144 oraz planuje dalsz\u0105 diagnostyk\u0119 lub leczenie.","Dbamy o komfort, bezpiecze\u0144stwo i dyskrecj\u0119 na ka\u017Cdym etapie diagnostyki i leczenia.","Prowadzimy r\xF3wnie\u017C leczenie biologiczne. Polega ono na podawaniu preparat\xF3w biologicznych, kt\xF3re zmniejszaj\u0105 odpowied\u017A zapaln\u0105 w organizmie - \u0142agodz\u0105 objawy i zatrzymuj\u0105 dalszy rozw\xF3j choroby. Terapia jest przeznaczona dla pacjent\xF3w z zaawansowanymi chorobami autoimmunologicznymi, opornymi na leczenie konwencjonalne, kt\xF3rzy nie mog\u0105 wzi\u0105\u0107 udzia\u0142u w badaniach klinicznych.","W AmiCare stosujemy dwa preparaty: Yuflyma (adalimumab) i Remsima (infliksymab). Ca\u0142y proces przebiega zgodnie z aktualnymi wytycznymi, pod nadzorem lekarzy specjalist\xF3w z do\u015Bwiadczeniem w tym zakresie. Koszt ustalamy indywidualnie po pierwszej wizycie u specjalisty."],listy:[{tytul:"W naszej pracowni endoskopii wykonujemy",punkty:["gastroskopi\u0119 (badanie g\xF3rnego odcinka przewodu pokarmowego)","kolonoskopi\u0119 (badanie jelita grubego)"]},{tytul:"Formy znieczulenia",punkty:["znieczulenie miejscowe (z u\u017Cyciem lidokainy)","analgosedacja (sedacja do\u017Cylna zapewniaj\u0105ca komfort i ograniczenie odczu\u0107 b\xF3lowych)","znieczulenie anestezjologiczne w obecno\u015Bci lekarza anestezjologa"]},{tytul:"Zabiegi diagnostyczne i terapeutyczne",punkty:["usuwanie polip\xF3w (polipektomia)","pobieranie wycink\xF3w do bada\u0144 histopatologicznych","tamowanie drobnych krwawie\u0144 z przewodu pokarmowego","ocena zmian zapalnych i nowotworowych"]},{tytul:"Wskazania do leczenia biologicznego",punkty:["choroby zapalne jelit: choroba Le\u015Bniowskiego-Crohna, wrzodziej\u0105ce zapalenie jelita grubego","choroby reumatyczne: reumatoidalne zapalenie staw\xF3w, zesztywniaj\u0105ce zapalenie staw\xF3w kr\u0119gos\u0142upa, m\u0142odzie\u0144cze idiopatyczne zapalenie staw\xF3w, \u0142uszczycowe zapalenie staw\xF3w","choroby dermatologiczne: \u0142uszczyca, atopowe zapalenie sk\xF3ry, pokrzywka idiopatyczna"]},{tytul:"Dlaczego warto nas wybra\u0107",punkty:["nowoczesny sprz\u0119t endoskopowy","r\xF3\u017Cne opcje znieczulenia dopasowane do potrzeb pacjenta","mo\u017Cliwo\u015B\u0107 wykonania diagnostyki i zabiegu podczas jednej wizyty","opieka do\u015Bwiadczonego zespo\u0142u specjalist\xF3w","przyjazne podej\u015Bcie do dzieci i doros\u0142ych"]}],kafelkiNaglowek:"Terapia biologiczna",kafelki:[{nazwa:"Leczenie biologiczne",opis:"Terapia preparatami biologicznymi (Yuflyma, Remsima) w nieswoistych chorobach zapalnych jelit - chorobie Le\u015Bniowskiego-Crohna i wrzodziej\u0105cym zapaleniu jelita grubego. Podanie leku pod nadzorem zespo\u0142u medycznego.",link:"/badania-diagnostyczne/leczenie-biologiczne"}],cenniki:[{naglowek:"Konsultacje",weekend:!1,pozycje:[{usluga:"Konsultacja Gastroenterologiczna",cena:"od 300 do 350 z\u0142"},{usluga:"Konsultacja Gastroenterologiczna w weekend",cena:"od 400 do 450 z\u0142"},{usluga:"Leczenie biologiczne (Yuflyma, Remsima)",cena:"ustalana indywidualnie po pierwszej wizycie"}]},{naglowek:"Gastroskopia",weekend:!0,pozycje:[{usluga:"Gastroskopia (z testem na Helicobacter pylori)",cena:"550z\u0142",cenaWeekend:"600z\u0142"},{usluga:"Gastroskopia w znieczuleniu analgosedacji (z testem na Helicobacter pylori)",cena:"900z\u0142",cenaWeekend:"1100z\u0142"},{usluga:"Gastroskopia w znieczuleniu og\xF3lnym (z testem na Helicobacter pylori)",cena:"1000z\u0142",cenaWeekend:"n/d"}]},{naglowek:"Kolonoskopia",weekend:!0,pozycje:[{usluga:"Kolonoskopia",cena:"650z\u0142",cenaWeekend:"700z\u0142"},{usluga:"Kolonoskopia w znieczuleniu analgosedacji",cena:"1000z\u0142",cenaWeekend:"1200z\u0142"},{usluga:"Kolonoskopia w znieczuleniu og\xF3lnym",cena:"1100z\u0142",cenaWeekend:"n/d"},{usluga:"Sigmoidoskopia",cena:"500z\u0142",cenaWeekend:"n/d"}]},{naglowek:"Kolonoskopia + Gastroskopia",weekend:!0,pozycje:[{usluga:"Kolonoskopia + Gastroskopia",cena:"1300z\u0142"},{usluga:"Kolonoskopia + Gastroskopia w znieczuleniu analgosedacji",cena:"1600z\u0142",cenaWeekend:"2000z\u0142"},{usluga:"Kolonoskopia + Gastroskopia w znieczuleniu og\xF3lnym",cena:"2500z\u0142"}]}],lekarze:["dr n. med. Hubert Zatorski","lek. Micha\u0142 Stasiak","lek. Magdalena Bara\u0144ska","dr n. med. Milena Padysz","dr n. med. Dariusz Krzyczmanik","lek. Julia Banasik","dr n. med. i n. o zdr. Danuta Dom\u017Ca\u0142-Magrowska","Dr n. med. Izabela Kubi\u0144ska","Dr n.med. Krzysztof Grzegorczyk","Dr n. med. Rafa\u0142 Drozda"]},{slug:"hepatologia",nazwa:"Hepatologia",opis:["Hepatologia zajmuje si\u0119 chorobami w\u0105troby, dr\xF3g \u017C\xF3\u0142ciowych i trzustki. Do konsultacji hepatologicznej najcz\u0119\u015Bciej kieruje wynik bada\u0144 krwi: podwy\u017Cszone pr\xF3by w\u0105trobowe (ALT, AST, GGTP, bilirubina) albo obraz st\u0142uszczenia w\u0105troby opisany w USG jamy brzusznej.","W\u0105troba d\u0142ugo nie boli. Choroba potrafi rozwija\u0107 si\u0119 latami bez wyra\u017Anych objaw\xF3w, a pierwszym sygna\u0142em bywa przypadkowo wykonane badanie. Dlatego nieprawid\u0142owego wyniku pr\xF3b w\u0105trobowych nie warto zostawia\u0107 bez wyja\u015Bnienia - nawet gdy nic nie dolega.","W AmiCare konsultacje hepatologiczne prowadzi dr n. med. Joanna Zboi\u0144ska - specjalistka chor\xF3b zaka\u017Anych i hepatolog, kt\xF3ra sama wykonuje elastografi\u0119 w\u0105troby. Podczas wizyty analizuje dotychczasowe wyniki, przeprowadza szczeg\xF3\u0142owy wywiad i planuje dalsz\u0105 diagnostyk\u0119 lub leczenie.","Diagnostyk\u0119 wykonujemy na miejscu: badania krwi, USG jamy brzusznej oraz - je\u015Bli obraz kliniczny tego wymaga - gastroskopi\u0119 i kolonoskopi\u0119 w naszej pracowni endoskopii.","Podczas konsultacji wykonujemy elastografi\u0119 w\u0105troby aparatem Hepatus. Zdrowa w\u0105troba jest mi\u0119kka, zw\u0142\xF3knia\u0142a twardnieje - a fala spr\u0119\u017Cysta przechodzi przez tward\u0105 tkank\u0119 szybciej. Aparat wysy\u0142a tak\u0105 fal\u0119 przez sk\xF3r\u0119 i mierzy jej pr\u0119dko\u015B\u0107, przeliczaj\u0105c j\u0105 na sztywno\u015B\u0107 w\u0105troby w kilopaskalach. Wynik odpowiada stopniowi w\u0142\xF3knienia w skali od F0 do F4, gdzie F4 oznacza marsko\u015B\u0107.","Drugi pomiar dotyczy st\u0142uszczenia. T\u0142uszcz w w\u0105trobie t\u0142umi fal\u0119 ultrad\u017Awi\u0119kow\u0105, wi\u0119c aparat liczy, ile z niej uby\u0142o po drodze, i podaje stopie\u0144 st\u0142uszczenia od S0 do S3. Jedno badanie odpowiada wi\u0119c na dwa pytania naraz: ile t\u0142uszczu od\u0142o\u017Cy\u0142o si\u0119 w w\u0105trobie i jak daleko posun\u0119\u0142o si\u0119 w\u0142\xF3knienie.","Hepatus pokazuje przy tym obraz USG, wi\u0119c lekarz widzi, w co celuje - omija naczynia, \u017Cebra i zmiany ogniskowe, kt\xF3re zafa\u0142szowa\u0142yby pomiar. Aparat pobiera dziesi\u0119\u0107 pomiar\xF3w pod rz\u0105d i odrzuca te wykonane w z\u0142ym momencie oddechu lub przy zbyt mocnym nacisku g\u0142owicy. Wynik pochodzi z mediany tego, co zosta\u0142o.","Do niedawna tak\u0105 odpowied\u017A dawa\u0142a dopiero biopsja: ig\u0142a, znieczulenie, kilka godzin obserwacji i ryzyko krwawienia. Elastografia zajmuje kilka minut, nie narusza sk\xF3ry i mo\u017Cna j\u0105 powtarza\u0107 co p\xF3\u0142 roku. W st\u0142uszczeniowej chorobie w\u0105troby, wirusowym zapaleniu typu B i C oraz w chorobach autoimmunologicznych zast\u0105pi\u0142a biopsj\u0119 w rutynowym monitorowaniu - ig\u0142a zostaje dla przypadk\xF3w, w kt\xF3rych rozpoznanie pozostaje niejasne.","Powt\xF3rzone badanie pokazuje kierunek. Spadek sztywno\u015Bci po roku leczenia oznacza, \u017Ce w\u0142\xF3knienie si\u0119 cofa; wzrost - \u017Ce terapi\u0119 trzeba zmieni\u0107. Przy st\u0142uszczeniu efekty diety i redukcji masy cia\u0142a wida\u0107 w wyniku wcze\u015Bniej ni\u017C w pr\xF3bach w\u0105trobowych."],listy:[{tytul:"Zajmujemy si\u0119 mi\u0119dzy innymi",punkty:["st\u0142uszczeniow\u0105 chorob\u0105 w\u0105troby (w tym niealkoholow\u0105)","przewlek\u0142ymi wirusowymi zapaleniami w\u0105troby typu B i C","autoimmunologicznymi chorobami w\u0105troby i dr\xF3g \u017C\xF3\u0142ciowych","polekowym i toksycznym uszkodzeniem w\u0105troby","w\u0142\xF3knieniem i marsko\u015Bci\u0105 w\u0105troby oraz ich powik\u0142aniami","kamic\u0105 \u017C\xF3\u0142ciow\u0105 i chorobami dr\xF3g \u017C\xF3\u0142ciowych","przewlek\u0142ym zapaleniem trzustki"]},{tytul:"Kiedy zg\u0142osi\u0107 si\u0119 do hepatologa",punkty:["nieprawid\u0142owe pr\xF3by w\u0105trobowe w badaniach krwi","st\u0142uszczenie lub inne zmiany w\u0105troby opisane w USG","przewlek\u0142e zm\u0119czenie, \u015Bwi\u0105d sk\xF3ry, za\u017C\xF3\u0142cenie sk\xF3ry lub oczu","b\xF3l w prawym pod\u017Cebrzu, nudno\u015Bci, brak apetytu","rozpoznana cukrzyca, oty\u0142o\u015B\u0107 lub zaburzenia lipidowe - to czynniki ryzyka st\u0142uszczenia w\u0105troby","przewlek\u0142e przyjmowanie lek\xF3w obci\u0105\u017Caj\u0105cych w\u0105trob\u0119"]},{tytul:"Diagnostyka dost\u0119pna na miejscu",punkty:["pobranie krwi i badania laboratoryjne","USG jamy brzusznej","elastografia w\u0105troby aparatem Hepatus - w\u0142\xF3knienie i st\u0142uszczenie","gastroskopia i kolonoskopia w pracowni endoskopii","pobranie wycink\xF3w do badania histopatologicznego podczas endoskopii"]},{tytul:"Elastografia krok po kroku",punkty:["przychodzisz na czczo - ostatni posi\u0142ek co najmniej 3 godziny przed badaniem","k\u0142adziesz si\u0119 na plecach, praw\u0105 r\u0119k\u0119 zak\u0142adasz za g\u0142ow\u0119, \u017Ceby rozsun\u0105\u0107 \u017Cebra","lekarz smaruje sk\xF3r\u0119 \u017Celem i przyk\u0142ada g\u0142owic\u0119 mi\u0119dzy \u017Cebrami, po prawej stronie","przy ka\u017Cdym pomiarze wstrzymujesz oddech na sekund\u0119 - pomiar\xF3w jest oko\u0142o dziesi\u0119ciu","ca\u0142o\u015B\u0107 zajmuje 5-10 minut, nie boli i nie wymaga znieczulenia","wynik dostajesz od razu, razem z om\xF3wieniem przez lekarza"]},{tytul:"Kiedy elastografia ma sens",punkty:["st\u0142uszczenie w\u0105troby opisane w USG - odpowiada, czy zd\u0105\u017Cy\u0142o ju\u017C uszkodzi\u0107 tkank\u0119","przewlek\u0142e wirusowe zapalenie w\u0105troby typu B lub C","podwy\u017Cszone pr\xF3by w\u0105trobowe utrzymuj\u0105ce si\u0119 mimo leczenia","kontrola po roku diety i redukcji masy cia\u0142a - czy zmiany si\u0119 cofn\u0119\u0142y","cukrzyca typu 2 i oty\u0142o\u015B\u0107, przy kt\xF3rych w\u0105troba w\u0142\xF3knieje bez objaw\xF3w","d\u0142ugotrwa\u0142e przyjmowanie lek\xF3w obci\u0105\u017Caj\u0105cych w\u0105trob\u0119"]},{tytul:"Kiedy wynik bywa niemiarodajny",punkty:["wodobrzusze - p\u0142yn w jamie brzusznej rozprasza fal\u0119","w\u0105skie przestrzenie mi\u0119dzy\u017Cebrowe, przez kt\xF3re nie da si\u0119 ustawi\u0107 g\u0142owicy","znaczna oty\u0142o\u015B\u0107, przy kt\xF3rej droga fali przez tkank\u0119 podsk\xF3rn\u0105 jest zbyt d\u0142uga","ostre zapalenie w\u0105troby i zast\xF3j \u017Cylny w niewydolno\u015Bci serca - obrz\u0119k zawy\u017Ca sztywno\u015B\u0107","niedawny posi\u0142ek, dlatego badanie robimy na czczo"]}],cenniki:[{naglowek:"Konsultacje",weekend:!1,pozycje:[{usluga:"Konsultacja hepatologiczna",cena:"300 z\u0142"},{usluga:"Konsultacja hepatologiczna z elastografi\u0105 w\u0105troby",cena:"400 z\u0142"}]}],lekarze:["Dr n. med. Joanna Zboi\u0144ska"]},{slug:"chirurgia",nazwa:"Chirurgia",opis:["Oferujemy ambulatoryjn\u0105 opiek\u0119 chirurgiczn\u0105, obejmuj\u0105c\u0105 konsultacje oraz drobne zabiegi wykonywane w komfortowych i bezpiecznych warunkach.","Zapewniamy indywidualne podej\u015Bcie do pacjenta oraz dba\u0142o\u015B\u0107 o najwy\u017Csze standardy bezpiecze\u0144stwa i higieny."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje chirurgiczne","usuwanie szw\xF3w","zmian\u0119 opatrunk\xF3w","usuwanie znamion sk\xF3rnych","kwalifikacj\u0119 do dalszego leczenia chirurgicznego","kontrol\u0119 po zabiegach"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja chirurgiczna",cena:"350z\u0142"},{usluga:"Usuni\u0119cie szw\xF3w wraz z konsultacj\u0105",cena:"od 450z\u0142"},{usluga:"Wizyta kontrolna",cena:"200z\u0142"},{usluga:"Naci\u0119cie zakrzepu brze\u017Cnego",cena:"od 700z\u0142"},{usluga:"Zmiana opatrunku",cena:"od 250z\u0142"},{usluga:"Usuwanie znamion sk\xF3rnych",cena:"350-600z\u0142 (ka\u017Cdy kolejny 100z\u0142)"}]}],lekarze:["Dr n. med. Rafa\u0142 Drozda"]},{slug:"reumatologia",nazwa:"Reumatologia",opis:["Zajmujemy si\u0119 diagnostyk\u0105 oraz leczeniem chor\xF3b uk\u0142adu ruchu i schorze\u0144 reumatycznych. Pomagamy pacjentom zmagaj\u0105cym si\u0119 z b\xF3lem staw\xF3w, stanami zapalnymi oraz chorobami autoimmunologicznymi.","Nowoczesna diagnostyka obrazowa pozwala na szybk\u0105 i precyzyjn\u0105 ocen\u0119 stanu zdrowia pacjenta."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje reumatologiczne","badania USG narz\u0105du ruchu (staw\xF3w, \u015Bci\u0119gien, tkanek mi\u0119kkich)","diagnostyk\u0119 zmian zapalnych i zwyrodnieniowych","monitorowanie przebiegu leczenia"]}],kafelkiNaglowek:"Terapia biologiczna",kafelki:[{nazwa:"Leczenie biologiczne",opis:"Terapia preparatami biologicznymi (Yuflyma, Remsima) w reumatoidalnym i \u0142uszczycowym zapaleniu staw\xF3w, zesztywniaj\u0105cym zapaleniu staw\xF3w kr\u0119gos\u0142upa oraz m\u0142odzie\u0144czym idiopatycznym zapaleniu staw\xF3w.",link:"/badania-diagnostyczne/leczenie-biologiczne"}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja reumatologiczna",cena:"300z\u0142"},{usluga:"USG barku",cena:"200z\u0142"},{usluga:"USG r\u0119ki",cena:"200z\u0142"},{usluga:"USG stawu kolanowego",cena:"200z\u0142"},{usluga:"USG stawu skokowego",cena:"200z\u0142"},{usluga:"USG stawu \u0142okciowego",cena:"200z\u0142"},{usluga:"USG staw\xF3w barkowych",cena:"300z\u0142"},{usluga:"USG staw\xF3w kolanowych",cena:"300z\u0142"},{usluga:"USG staw\xF3w skokowych",cena:"300z\u0142"}]}],lekarze:["Dr Joanna Kowalska-Majka","lek. Natalia Wili\u0144ska-Spa\u0142ka"]},{slug:"kardiologia",nazwa:"Kardiologia",opis:["Oferujemy kompleksow\u0105 opiek\u0119 kardiologiczn\u0105, obejmuj\u0105c\u0105 profilaktyk\u0119, diagnostyk\u0119 oraz leczenie chor\xF3b serca i uk\u0142adu kr\u0105\u017Cenia.","Zapewniamy profesjonaln\u0105 opiek\u0119 oraz nowoczesny sprz\u0119t diagnostyczny, co pozwala na szybkie i trafne rozpoznanie problem\xF3w kardiologicznych."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje kardiologiczne","badania EKG (elektrokardiografia)","badania ECHO serca (echokardiografia)","ocen\u0119 ryzyka sercowo-naczyniowego","diagnostyk\u0119 zaburze\u0144 rytmu serca i nadci\u015Bnienia"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja kardiologiczna",cena:"250z\u0142"},{usluga:"Konsultacja kardiologiczna + ECHO",cena:"350z\u0142"},{usluga:"USG serca (echo serca)",cena:"220z\u0142"},{usluga:"EKG spoczynkowe",cena:"40z\u0142"},{usluga:"EKG spoczynkowe z opisem kardiologa",cena:"90z\u0142"}]}],lekarze:["lek. \u0141ukasz Spadli\u0144ski","Dr n.med. Adam Rafa\u0142 Poliwczak"]},{slug:"medycyna-rodzinna",nazwa:"Medycyna rodzinna",opis:["Lekarz rodzinny prowadzi pacjenta od pierwszego objawu do rozpoznania: bada, zleca badania, interpretuje wyniki i kieruje do specjalisty tylko wtedy, gdy jest to potrzebne. To najkr\xF3tsza droga, gdy nie wiadomo, do kogo si\u0119 zg\u0142osi\u0107.","Przyjmujemy doros\u0142ych i dzieci. Wizyta obejmuje wywiad, badanie fizykalne i plan dalszego post\u0119powania - z recept\u0105, zwolnieniem lub skierowaniem na badania wykonywane u nas na miejscu.","Konsultacje prowadzi lek. Kacper Mazur, lekarz w trakcie specjalizacji z medycyny rodzinnej, zajmuj\u0105cy si\u0119 tak\u017Ce medycyn\u0105 podr\xF3\u017Cy i leczeniem oty\u0142o\u015Bci."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje internistyczne i pediatryczne","interpretacj\u0119 wynik\xF3w bada\u0144 laboratoryjnych i obrazowych","prowadzenie chor\xF3b przewlek\u0142ych: nadci\u015Bnienia, cukrzycy, zaburze\u0144 lipidowych","infekcje ostre - diagnostyk\u0119 i leczenie","recepty, zwolnienia i skierowania na dalsz\u0105 diagnostyk\u0119","kwalifikacj\u0119 do szczepie\u0144 i konsultacje przed wyjazdem zagranicznym","leczenie oty\u0142o\u015Bci i prowadzenie redukcji masy cia\u0142a"]},{tytul:"Kiedy um\xF3wi\u0107 wizyt\u0119",punkty:["objawy, przy kt\xF3rych nie wiadomo, do jakiego specjalisty si\u0119 zg\u0142osi\u0107","nieprawid\u0142owy wynik badania krwi wymagaj\u0105cy om\xF3wienia","przewlek\u0142a choroba wymagaj\u0105ca kontroli i modyfikacji leczenia","gor\u0105czka, kaszel, b\xF3l gard\u0142a i inne infekcje","planowana podr\xF3\u017C do kraju o odmiennych warunkach sanitarnych"]}],cenniki:[],lekarze:["lek. Kacper Mazur"]},{slug:"dermatologia",nazwa:"Dermatologia",opis:["Zajmujemy si\u0119 diagnostyk\u0105 i leczeniem chor\xF3b sk\xF3ry, w\u0142os\xF3w i paznokci u doros\u0142ych i dzieci. Podstaw\u0105 wizyty jest ogl\u0105danie zmian w dermatoskopie - powi\u0119kszenie pokazuje struktur\u0119, kt\xF3rej nie wida\u0107 go\u0142ym okiem.","Prowadzimy choroby przewlek\u0142e wymagaj\u0105ce d\u0142ugiego leczenia: \u0142uszczyc\u0119, atopowe zapalenie sk\xF3ry, tr\u0105dzik. W tych schorzeniach efekt daje plan rozpisany na miesi\u0105ce, a nie jednorazowa recepta - dlatego umawiamy wizyty kontrolne i korygujemy terapi\u0119 na bie\u017C\u0105co.","Konsultacje prowadzi lek. Klaudia Kubikowska-Mazur, cz\u0142onkini Polskiego Towarzystwa Dermatologicznego i European Academy of Dermatology and Venereology."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje dermatologiczne dla doros\u0142ych i dzieci","dermatoskopow\u0105 ocen\u0119 znamion","leczenie \u0142uszczycy, atopowego zapalenia sk\xF3ry i tr\u0105dziku","diagnostyk\u0119 i leczenie grzybic sk\xF3ry i paznokci","choroby w\u0142os\xF3w i sk\xF3ry ow\u0142osionej g\u0142owy - \u0142ysienie, \u0142upie\u017C","zmiany sk\xF3rne o pod\u0142o\u017Cu alergicznym, w tym pokrzywk\u0119"]},{tytul:"Kiedy zg\u0142osi\u0107 si\u0119 do dermatologa",punkty:["znami\u0119, kt\xF3re zmienia kszta\u0142t, kolor lub wielko\u015B\u0107","wysypka, \u015Bwi\u0105d lub zmiany sk\xF3rne utrzymuj\u0105ce si\u0119 mimo leczenia","nawracaj\u0105cy tr\u0105dzik u nastolatka lub osoby doros\u0142ej","zmiany na paznokciach: przebarwienia, kruszenie, pogrubienie p\u0142ytki","wypadanie w\u0142os\xF3w lub przerzedzenie ow\u0142osienia g\u0142owy"]}],cenniki:[],lekarze:["lek. Klaudia Kubikowska-Mazur"]},{slug:"psychologia",nazwa:"Psychologia",opis:["Prowadzimy konsultacje, terapi\u0119 i diagnoz\u0119 psychologiczn\u0105 dla dzieci, m\u0142odzie\u017Cy i doros\u0142ych.","Nasz zesp\xF3\u0142 tworz\u0105 wykwalifikowani psycholodzy, terapeuci i mediatorzy, kt\xF3rzy \u0142\u0105cz\u0105 wieloletnie do\u015Bwiadczenie z empatycznym podej\u015Bciem do ka\u017Cdego pacjenta. Pracujemy z osobami w r\xF3\u017Cnym wieku i w r\xF3\u017Cnych sytuacjach \u017Cyciowych, zapewniaj\u0105c fachow\u0105 pomoc opart\u0105 na rzetelnej wiedzy i szacunku.","Form\u0119 terapii dobieramy po rozpoznaniu sytuacji pacjenta - do jego mo\u017Cliwo\u015Bci, cel\xF3w i tempa pracy.","Tworzymy atmosfer\u0119 pe\u0142n\u0105 zrozumienia, \u017Cyczliwo\u015Bci i zaufania. Nasze gabinety to przestrze\u0144, w kt\xF3rej mo\u017Cesz m\xF3wi\u0107 swobodnie, bez oceniania i obaw.","Pierwsza wizyta trwa 50 minut i s\u0142u\u017Cy rozpoznaniu problemu oraz ustaleniu dalszych krok\xF3w."],listy:[{tytul:"Oferta",punkty:["Kompleksowa oferta psychologiczna - diagnoza psychologiczna, terapia i specjalistyczne wsparcie dostosowane do indywidualnych potrzeb","Diagnoza psychologiczna - korzystamy z nowoczesnych metod, takich jak test inteligencji Stanford-Binet","TUS - Trening Umiej\u0119tno\u015Bci Spo\u0142ecznych, skuteczna metoda wspieraj\u0105ca dzieci i m\u0142odzie\u017C w budowaniu relacji, asertywno\u015Bci i kontroli emocji"]}],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacje (50 minut) - pierwsza wizyta",cena:"220 z\u0142"},{usluga:"Konsultacje (50 minut) - kolejna wizyta",cena:"200 z\u0142"},{usluga:"Terapia psychologiczna (50 minut) - pierwsza wizyta",cena:"220 z\u0142"},{usluga:"Terapia psychologiczna (50 minut) - kolejna wizyta",cena:"200 z\u0142"},{usluga:"Mediacje (60 minut) - pierwsza wizyta",cena:"450 z\u0142"},{usluga:"Mediacje (60 minut) - kolejna wizyta",cena:"400 z\u0142"},{usluga:"Za\u015Bwiadczenie psychologa",cena:"160 z\u0142"},{usluga:"Opinia psychologiczna",cena:"160 z\u0142"},{usluga:"Konsultacja diagnostyczna",cena:"280 z\u0142"},{usluga:"Skala Inteligencji Stanford-Binet 5 (SB5)",cena:"300 z\u0142"},{usluga:"Diagnoza spektrum autyzmu (5 wizyt) bez ADOS + wizyta u lekarza zgodnie z cennikiem",cena:"od 2100 z\u0142"},{usluga:"Diagnoza spektrum autyzmu (5 wizyt) z ADOS + wizyta u lekarza zgodnie z cennikiem",cena:"od 3000 z\u0142"},{usluga:"Test ADOS - raport z badania, wywiad 50 minut + test (2x50 minut)",cena:"od 1200 z\u0142"},{usluga:"MMPI-2 - pierwsza wizyta wywiad, druga i trzecia wizyta test",cena:"1100-1400 z\u0142"}]}],lekarze:["Dominika Buczy\u0144ska"]},{slug:"dietetyka",nazwa:"Dietetyka",opis:["Oferujemy profesjonalne wsparcie dietetyczne, oparte na indywidualnym podej\u015Bciu do potrzeb pacjenta. Pomagamy w poprawie nawyk\xF3w \u017Cywieniowych, redukcji masy cia\u0142a, budowaniu zdrowej sylwetki oraz wspieraniu leczenia diet\u0105 w r\xF3\u017Cnych jednostkach chorobowych.","Ka\u017Cdy plan \u017Cywieniowy opracowywany jest w oparciu o szczeg\xF3\u0142owy wywiad, uwzgl\u0119dniaj\u0105cy tryb \u017Cycia, aktywno\u015B\u0107 fizyczn\u0105, wyniki bada\u0144 oraz ewentualne choroby wsp\xF3\u0142istniej\u0105ce.","Pomagamy osi\u0105gn\u0105\u0107 trwa\u0142e efekty w zdrowy i bezpieczny spos\xF3b."],listy:[{tytul:"Zakres us\u0142ug obejmuje",punkty:["konsultacje dietetyczne","wizyty kontrolne monitoruj\u0105ce post\u0119py","analiz\u0119 sk\u0142adu cia\u0142a (m.in. poziom tkanki t\u0142uszczowej, masy mi\u0119\u015Bniowej i nawodnienia)","indywidualne jad\u0142ospisy dostosowane do stylu \u017Cycia, preferencji oraz stanu zdrowia","plany \u017Cywieniowe na 7, 14, 21 oraz 30 dni"]},{tytul:"Dlaczego warto skorzysta\u0107 z naszej opieki dietetycznej",punkty:["indywidualne podej\u015Bcie do ka\u017Cdego pacjenta","realne i mo\u017Cliwe do utrzymania zalecenia","wsparcie na ka\u017Cdym etapie zmiany nawyk\xF3w","jad\u0142ospisy dopasowane do codziennego trybu \u017Cycia","kompleksowe podej\u015Bcie do zdrowia i samopoczucia"]}],cenniki:[],lekarze:["mgr Paulina Kruk","Oliwia \u015Acigalska"]},{slug:"proktologia",nazwa:"Proktologia",opis:["Proktologia to dziedzina medycyny zajmuj\u0105ca si\u0119 diagnostyk\u0105, leczeniem oraz profilaktyk\u0105 chor\xF3b ko\u0144cowego odcinka przewodu pokarmowego - odbytnicy, kana\u0142u odbytu i okolic odbytu. Cho\u0107 schorzenia proktologiczne cz\u0119sto nale\u017C\u0105 do temat\xF3w kr\u0119puj\u0105cych dla pacjent\xF3w, ich wczesne rozpoznanie i odpowiednie leczenie pozwalaj\u0105 skutecznie wyeliminowa\u0107 dolegliwo\u015Bci oraz zapobiec powa\u017Cniejszym powik\u0142aniom.","W AmiCare zapewniamy kompleksow\u0105 opiek\u0119 proktologiczn\u0105 obejmuj\u0105c\u0105 konsultacje specjalistyczne, diagnostyk\u0119 oraz dob\xF3r indywidualnego leczenia. Zajmujemy si\u0119 rozpoznawaniem i leczeniem najcz\u0119stszych schorze\u0144 proktologicznych, takich jak hemoroidy, szczeliny odbytu, przetoki, ropnie oko\u0142oodbytnicze, polipy oraz innych chor\xF3b ko\u0144cowego odcinka jelita grubego.","Do objaw\xF3w, kt\xF3re powinny sk\u0142oni\u0107 do konsultacji z proktologiem, nale\u017C\u0105 mi\u0119dzy innymi: b\xF3l podczas wypr\xF3\u017Cniania, krwawienie z odbytu, \u015Bwi\u0105d, pieczenie, uczucie dyskomfortu lub niepe\u0142nego wypr\xF3\u017Cnienia, a tak\u017Ce przewlek\u0142e zaparcia lub biegunki. Wiele schorze\u0144 proktologicznych rozwija si\u0119 stopniowo, dlatego nie warto odk\u0142ada\u0107 wizyty u specjalisty.","Pacjentami poradni proktologicznej AmiCare opiekuje si\u0119 dr n. med. Rafa\u0142 Drozda - specjalista chirurgii og\xF3lnej i onkologicznej, gastroenterolog oraz proktolog, od lat zajmuj\u0105cy si\u0119 diagnostyk\u0105 i leczeniem chor\xF3b przewodu pokarmowego oraz schorze\u0144 proktologicznych.","Dbamy o komfort, dyskrecj\u0119 i bezpiecze\u0144stwo ka\u017Cdego pacjenta, zapewniaj\u0105c profesjonaln\u0105 opiek\u0119 medyczn\u0105 oraz indywidualne podej\u015Bcie na ka\u017Cdym etapie diagnostyki i leczenia."],cenniki:[{weekend:!1,pozycje:[{usluga:"Konsultacja proktologiczna",cena:"350z\u0142"}]}],lekarze:["Dr n. med. Rafa\u0142 Drozda"]}];export{a};
